steps.action:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issue(identifier: \"ENG-7\") { id identifier title blockingIssues { nodes { id identifier title } } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues(first: 20, orderBy: priority) { nodes { id identifier title team { key } relations { nodes { id relatedIssue { id identifier title } type } } } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues(first: 50) { nodes { id identifier title team { key } relations { nodes { id relatedIssue { id identifier title } type } } } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "mutation { issueRelationDelete(id: \"r-1\") { success } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issue(id: \"i-eng-7\") { id identifier title relations { nodes { id relatedIssue { identifier title } type } } } }"
}'
